import{z as d,x as A,o as s,c as p,q as l,j as i,D as r,d as t,s as E,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"栈式对寄存器式 VM","description":"","frontmatter":{"title":"栈式对寄存器式 VM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-vs-register-vm.md","filePath":"cs/stack-vs-register-vm.md","lastUpdated":1791413859000}'),B={name:"cs/stack-vs-register-vm.md"};function c(h,a,m,u,D,S){const o=A("Mermaid");return s(),p("div",null,[a[2]||(a[2]=l('<h1 id="栈式对寄存器式-vm" tabindex="-1">栈式对寄存器式 VM <a class="header-anchor" href="#栈式对寄存器式-vm" aria-label="Permalink to &quot;栈式对寄存器式 VM&quot;">​</a></h1><div class="epigraph"><p>栈式用隐式栈顶当操作数，编码短；寄存器式把操作数编号写进指令，少压栈，利于映射到真实寄存器与 JIT。</p><footer>—— 据 Shi et al., Virtual Machine Showdown；Davis et al., The Case for Virtual Register Machines；Java vs LuaJIT/Dalvik 对照整理</footer></div><p>上一课<a href="/cs/bytecode-interpreter">字节码解释器</a> 未钉操作数形态。缺口是 <strong>stack vs register</strong>：JVM 典型栈式；Lua 5、Dalvik 寄存器式。本课钉编码与分派成本，线程化下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>栈式：<code>iadd</code> 无操作数字段。编译简单（表达式 SDT 自然）。执行：多次 push/pop，解释器内存流量大。寄存器式：<code>add r1,r2,r3</code>，编译要做一次「虚拟寄存器分配」（可简化）。缺口是<strong>这笔税</strong>，不是 GC。</p><p>Showdown 论文：寄存器式解释往往少指令数，但指令更大。</p><h3 id="虚拟寄存器不是物理寄存器" tabindex="-1">虚拟寄存器不是物理寄存器 <a class="header-anchor" href="#虚拟寄存器不是物理寄存器" aria-label="Permalink to &quot;虚拟寄存器不是物理寄存器&quot;">​</a></h3><p>VM 寄存器是解释器数组槽。JIT 再映射到硬件。不要把 Dalvik <code>v0</code> 当 <code>x0</code>。</p><p><span class="marginnote">Shi, Gregg, Beatty, Ertl。Davis 等。本课不把 WebAssembly 的操作数栈当已讲完，后课 wasm 再接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈式生成：后序遍历。寄存器式：把 SSA 名或栈槽编号写进指令。局部变量：JVM 用局部表+栈；寄存器 VM 把局部直接当寄存器。</p><p><span class="marginnote">数字实例：Shi et al. 的 Showdown 实测里，同一批基准程序寄存器式字节码的指令条数大约比栈式少 47%，但字节码总大小平均只大 25% 左右——单条指令更宽，换来条数更少，总派发次数下降才是收益来源。</span></p>',12)),(s(),i(n,null,{default:r(()=>[E(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXPR%5B%22%E8%A1%A8%E8%BE%BE%E5%BC%8F%22%5D%20--%3E%20STK%5B%22%E5%8E%8B%E6%A0%88%E8%BF%90%E7%AE%97%22%5D%0A%20%20EXPR%20--%3E%20REG%5B%22%E4%B8%89%E5%9C%B0%E5%9D%80%E5%AD%97%E8%8A%82%E7%A0%81%22%5D%0A%20%20STK%20--%3E%20INT%5B%22%E8%A7%A3%E9%87%8A%22%5D%0A%20%20REG%20--%3E%20INT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 SSA：寄存器 VM 更接近中端 IR，JIT 少一层 lowering。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"调用约定：栈式把参数压栈；寄存器式规定窗口或移动。异常与 GC 根：栈式要精确栈深度图；寄存器式要 live 寄存器位图。",-1)),a[6]||(a[6]=e("p",null,[t("以 "),e("code",null,"a = b + c"),t(" 为例，两种 VM 各自要跑哪些指令、压弹栈几次，直接决定解释循环里每步的内存流量。")],-1)),(s(),i(n,null,{default:r(()=>[E(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A0%81%20a%20%3D%20b%20%2B%20c%22%5D%20--%3E%20S1%5B%22%E6%A0%88%E5%BC%8F%3A%20load%20b%2C%20load%20c%22%5D%0A%20%20S1%20--%3E%20S2%5B%22iadd%3A%20%E5%BC%B9%E4%B8%A4%E4%B8%AA%E6%95%B0%20%E7%9B%B8%E5%8A%A0%20%E5%8E%8B%E5%9B%9E%22%5D%0A%20%20S2%20--%3E%20S3%5B%22store%20a%22%5D%0A%20%20SRC%20--%3E%20R1%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%BC%8F%3A%20add%20r0%2C%20r1%2C%20r2%22%5D%0A%20%20R1%20--%3E%20R2%5B%22move%20r0%20%E5%88%B0%E6%A7%BD%20a%20%E6%88%96%E7%9B%B4%E6%8E%A5%E7%BC%96%E5%9D%80%22%5D%0A%20%20S3%20--%3E%20CNT%5B%22%E6%A0%88%E5%BC%8F%E7%BA%A6%204%20%E6%9D%A1%E6%8C%87%E4%BB%A4%20%E5%A4%9A%E6%AC%A1%E5%8E%8B%E5%BC%B9%E6%A0%88%22%5D%0A%20%20R2%20--%3E%20CNT2%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%BC%8F%E7%BA%A6%202%20%E6%9D%A1%E6%8C%87%E4%BB%A4%20%E9%9B%B6%E5%8E%8B%E6%A0%88%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">术语翻译：压栈/弹栈（push/pop）就是把操作数放进栈顶、再从栈顶取出来的动作——栈式 VM 每做一次加法，操作数都要先进出内存数组两次，这就是「解释器内存流量大」的具体来源。</span></p><p>不要混用两种编码当「优化开关」而不改生成器。</p><p><span class="marginnote">初学者容易以为 Dalvik 的 <code>v0</code> 就是 CPU 的物理寄存器。实际上它只是解释器里一个 C 数组的下标，物理寄存器要等 JIT 编译时才由寄存器分配器二次映射；纯解释执行时它可能根本不碰任何硬件寄存器。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写线程化。后课默认：两种编码都是合法字节码。下一课线程化分派：减 switch 开销。</p><p>也不把寄存器 VM 当 GPU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>栈式编码密、解释器栈操作多；寄存器式指令少、编译稍复杂。</li><li>JIT 路径上寄存器式更近 SSA。</li><li>根枚举方式随编码变。</li><li>出处：Shi et al.；Davis et al.；对照 JVM 规范、Lua。</li></ul>',8))])}const v=d(B,[["render",c]]);export{T as __pageData,v as default};
